+    let preserved = skills.join("desk-tutor").join("skill.toml").is_file();
+    eprintln!("early-refusal: after_exit={after_exit} write={:?} half_close={:?} status_ok={ok} answer={answer} preserved={preserved}; journal={journal}", request.write, request.half_close);
     assert!(!ok, "{answer}");
